create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in('owner','staff')),created_at timestamptz default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),entry_date date not null,small_qty int default 0,big_qty int default 0,other_amount numeric(12,2) default 0,total_amount numeric(12,2) not null,payment_mode text default 'Cash',note text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),entry_date date not null,title text not null,amount numeric(12,2) not null,payment_mode text default 'Cash',note text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.udhar_entries(id uuid primary key default gen_random_uuid(),entry_date date not null,customer_name text not null,mobile text not null,amount numeric(12,2) not null,kind text not null check(kind in('given','paid')),note text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.loyalty_customers(id uuid primary key default gen_random_uuid(),customer_name text not null,mobile text unique not null,stamps int not null default 0 check(stamps between 0 and 5),free_chai int not null default 0,created_at timestamptz default now());
create table if not exists public.loyalty_events(id uuid primary key default gen_random_uuid(),customer_id uuid references public.loyalty_customers(id),event_type text not null,quantity int default 1,created_by uuid references auth.users(id),created_at timestamptz default now());
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
do $$ declare t text; begin foreach t in array array['profiles','sales','expenses','udhar_entries','loyalty_customers','loyalty_events'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profile own or owner" on public.profiles for select to authenticated using(id=auth.uid() or public.my_role()='owner');
create policy "sales read" on public.sales for select to authenticated using(public.my_role() in('owner','staff')); create policy "sales insert" on public.sales for insert to authenticated with check(public.my_role() in('owner','staff') and created_by=auth.uid()); create policy "sales owner update" on public.sales for update to authenticated using(public.my_role()='owner') with check(public.my_role()='owner'); create policy "sales owner delete" on public.sales for delete to authenticated using(public.my_role()='owner');
create policy "expenses read" on public.expenses for select to authenticated using(public.my_role() in('owner','staff')); create policy "expenses insert" on public.expenses for insert to authenticated with check(public.my_role() in('owner','staff') and created_by=auth.uid()); create policy "expenses owner update" on public.expenses for update to authenticated using(public.my_role()='owner') with check(public.my_role()='owner'); create policy "expenses owner delete" on public.expenses for delete to authenticated using(public.my_role()='owner');
create policy "udhar read" on public.udhar_entries for select to authenticated using(public.my_role() in('owner','staff')); create policy "udhar insert" on public.udhar_entries for insert to authenticated with check(public.my_role() in('owner','staff') and created_by=auth.uid()); create policy "udhar owner update" on public.udhar_entries for update to authenticated using(public.my_role()='owner') with check(public.my_role()='owner'); create policy "udhar owner delete" on public.udhar_entries for delete to authenticated using(public.my_role()='owner');
create policy "loyalty customer read" on public.loyalty_customers for select to authenticated using(public.my_role() in('owner','staff')); create policy "loyalty customer insert" on public.loyalty_customers for insert to authenticated with check(public.my_role() in('owner','staff')); create policy "loyalty customer update" on public.loyalty_customers for update to authenticated using(public.my_role() in('owner','staff')) with check(public.my_role() in('owner','staff'));
create policy "loyalty event read" on public.loyalty_events for select to authenticated using(public.my_role() in('owner','staff')); create policy "loyalty event insert" on public.loyalty_events for insert to authenticated with check(public.my_role() in('owner','staff') and created_by=auth.uid()); create policy "loyalty event owner delete" on public.loyalty_events for delete to authenticated using(public.my_role()='owner');
